// The API models keys as a map keyed by key name; Terraform models them as a list (write-only
// arguments aren't allowed inside sets). cak_wo is write-only, so it's read from the raw
// configuration by key name instead of from v.
func expandNetworkConnectivityInterconnectKeyGroupKeys(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	l, _ := v.([]interface{})
	if len(l) == 0 {
		return nil, nil
	}
	caks, _ := interconnectKeyGroupCaksFromConfig(d.GetRawConfig())
	keys := make(map[string]interface{}, len(l))
	for _, raw := range l {
		m, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		name, _ := m["name"].(string)
		if name == "" {
			continue
		}
		key := map[string]interface{}{
			"name":      name,
			"startTime": m["start_time"],
			"ckn":       m["ckn"],
		}
		if cak := caks[name]; cak != "" {
			key["cak"] = cak
		}
		keys[name] = key
	}
	return keys, nil
}

func expandNetworkConnectivityInterconnectKeyGroupEffectiveLabels(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (map[string]string, error) {
	if v == nil {
		return map[string]string{}, nil
	}
	m := make(map[string]string)
	for k, val := range v.(map[string]interface{}) {
		m[k] = val.(string)
	}
	return m, nil
}

func ResourceNetworkConnectivityInterconnectKeyGroupFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("create_time", flattenNetworkConnectivityInterconnectKeyGroupCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("update_time", flattenNetworkConnectivityInterconnectKeyGroupUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("labels", flattenNetworkConnectivityInterconnectKeyGroupLabels(res["labels"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("description", flattenNetworkConnectivityInterconnectKeyGroupDescription(res["description"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("keys", flattenNetworkConnectivityInterconnectKeyGroupKeys(res["keys"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("interconnects", flattenNetworkConnectivityInterconnectKeyGroupInterconnects(res["interconnects"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("terraform_labels", flattenNetworkConnectivityInterconnectKeyGroupTerraformLabels(res["labels"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}
	if err = d.Set("effective_labels", flattenNetworkConnectivityInterconnectKeyGroupEffectiveLabels(res["labels"], d, config)); err != nil {
		return fmt.Errorf("Error reading InterconnectKeyGroup: %s", err)
	}

	return nil
}
